class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        # 维护单调队列
        # 每次都首先移除队尾比它小的元素, 然后再加入, 这样就会使得队列始终是单调递减的
        q = deque()
        res = []
        for i, num in enumerate(nums):
            # 移除队尾比num小的元素
            while q and q[-1][1] < num:
                q.pop()
            q.append((i, num))
            # 移除队头不在窗口内的元素
            while q and q[0][0] <= i - k:
                q.popleft()

            if i >= k - 1:
                res.append(q[0][1])
        return res
